mapper.select:
select UNITE_ID uniteId, PRT_BAG_ID prtBagId, IND_ID indId, START_DATE startDate, END_DATE endDate, FINPROD_ID finprodId, WARN_COND warnCond, APPROVE_COND approveCond, FOUL_COND foulCond from RSK_INDIVID_SPECIAL_STAGE
UNITE_TYPE=#{uniteType}
and START_DATE <= str_to_date('${valDate}','%Y-%m-%d') AND END_DATE >= str_to_date('${valDate}','%Y-%m-%d')

select PORTFOLIO_ID, IND_ID, FOUL_DAYS from RSK_ISUP_POINT_VAL
SUP_FREQUENCY=#{supFrequency}
and SUP_DATE = str_to_date('${valDate}','%Y-%m-%d')
